import { connect } from 'cloudflare:sockets';

function timeoutPromise<T>(promise: Promise<T>, ms: number, errorMsg: string): Promise<T> {
  let timer: any;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error(errorMsg)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

// Helper to extract the 11-character video ID
function extractVideoId(url: string): string {
  const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
  const match = url.match(regExp);
  if (match && match[2].length === 11) {
    return match[2];
  }
  throw new Error("无法从链接中提取 YouTube 视频 ID");
}

async function fetchThirdPartyTranscript(videoId: string): Promise<string> {
  const url = `https://youtube-transcript.ai/transcript/${videoId}.txt`;
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`第三方接口状态码 ${res.status}`);
  }
  const text = await res.text();
  const index = text.indexOf('## Transcript');
  let bodyText = text;
  if (index !== -1) {
    bodyText = text.substring(index + 13).trim();
  }
  // Strip timestamps like [0:01] or [12:34]
  let cleaned = bodyText.replace(/\[\d+:\d+\]/g, '').replace(/\[\d+:\d+:\d+\]/g, '');
  const endSig = cleaned.indexOf('---');
  if (endSig !== -1) {
    cleaned = cleaned.substring(0, endSig);
  }
  return cleaned.trim();
}

// Format: IP:Port:Username:Password
async function proxyRequest(
  urlStr: string,
  proxyString: string,
  options: {
    method?: string;
    body?: string;
    headers?: Record<string, string>;
    cookie?: string;
  } = {}
): Promise<string> {
  const doRequest = async () => {
    const method = options.method || 'GET';
    const url = new URL(urlStr);
    const parts = proxyString.split(':');
    if (parts.length < 4) throw new Error("Invalid proxy format");
    
    const proxyHost = parts[0];
    const proxyPort = parseInt(parts[1]);
    const auth = btoa(`${parts[2]}:${parts[3]}`);
    
    const socket = connect({ hostname: proxyHost, port: proxyPort }, { secureTransport: 'starttls' } as any);
    const writer = socket.writable.getWriter();
    
    const connectReq = `CONNECT ${url.hostname}:443 HTTP/1.1\r\nHost: ${url.hostname}:443\r\nProxy-Authorization: Basic ${auth}\r\n\r\n`;
    await writer.write(new TextEncoder().encode(connectReq));
    writer.releaseLock();
    
    const reader = socket.readable.getReader();
    let connectRes = '';
    while (true) {
      const { done, value } = await reader.read();
      if (value) {
        connectRes += new TextDecoder().decode(value);
        if (connectRes.includes('\r\n\r\n')) break;
      }
      if (done) break;
    }
    reader.releaseLock();
    
    if (!connectRes.startsWith('HTTP/1.1 200') && !connectRes.startsWith('HTTP/1.0 200')) {
      throw new Error('Proxy CONNECT failed: ' + connectRes.split('\r\n')[0]);
    }
    
    const secureSocket = socket.startTls({ expectedServerHostname: url.hostname } as any);
    const secureWriter = secureSocket.writable.getWriter();
    
    const reqHeaders: Record<string, string> = {
      'Host': url.hostname,
      'Accept-Language': 'en-US,en;q=0.9',
      'Accept-Encoding': 'identity',
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Connection': 'close',
      ...options.headers
    };
    
    if (options.cookie) {
      reqHeaders['Cookie'] = options.cookie;
    }
    
    let bodyBytes: any = new Uint8Array(0);
    if (options.body) {
      bodyBytes = new TextEncoder().encode(options.body);
      reqHeaders['Content-Length'] = bodyBytes.length.toString();
    }
    
    let reqStr = `${method} ${url.pathname}${url.search} HTTP/1.0\r\n`;
    for (const [k, v] of Object.entries(reqHeaders)) {
      reqStr += `${k}: ${v}\r\n`;
    }
    reqStr += '\r\n';
    
    await secureWriter.write(new TextEncoder().encode(reqStr));
    if (bodyBytes.length > 0) {
      await secureWriter.write(bodyBytes);
    }
    secureWriter.releaseLock();
    
    const secureReader = secureSocket.readable.getReader();
    let responseText = '';
    while (true) {
      const { done, value } = await secureReader.read();
      if (value) {
        responseText += new TextDecoder().decode(value);
        
        const headerEnd = responseText.indexOf('\r\n\r\n');
        if (headerEnd !== -1) {
          const headers = responseText.substring(0, headerEnd);
          const clMatch = headers.match(/Content-Length:\s*(\d+)/i);
          const body = responseText.substring(headerEnd + 4);
          
          if (clMatch) {
            const cl = parseInt(clMatch[1]);
            if (new TextEncoder().encode(body).length >= cl) {
              break;
            }
          } else if (headers.toLowerCase().includes('transfer-encoding: chunked')) {
            if (responseText.endsWith('0\r\n\r\n')) {
              break;
            }
          }
        }
      }
      if (done) break;
    }
    secureReader.releaseLock();
    
    const headerEnd = responseText.indexOf('\r\n\r\n');
    if (headerEnd !== -1) {
      return responseText.substring(headerEnd + 4);
    }
    return responseText;
  };

  return timeoutPromise(doRequest(), 5000, `代理节点 ${proxyString.split(':')[0]} 连接超时`);
}

