async function fetchWatchPageCaptions(videoId: string, proxyString?: string, cookie?: string): Promise<string> {
  const watchUrl = `https://www.youtube.com/watch?v=${videoId}`;
  const headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
    'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8'
  };
  
  let html = '';
  if (proxyString) {
    html = await proxyRequest(watchUrl, proxyString, { headers, cookie });
  } else {
    const directHeaders: Record<string, string> = { ...headers };
    if (cookie) directHeaders['Cookie'] = cookie;
    const res = await fetch(watchUrl, { headers: directHeaders });
    if (!res.ok) throw new Error(`HTTP 状态码 ${res.status}`);
    html = await res.text();
  }
  
  const match = html.match(/ytInitialPlayerResponse\s*=\s*({.*?});/);
  if (!match) {
    throw new Error('未在页面中找到播放器元数据 (可能触发了人机验证/验证码)');
  }
  
  const parsed = JSON.parse(match[1]);
  const tracks = parsed?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
  if (!tracks || tracks.length === 0) {
    const playabilityStatus = parsed?.playabilityStatus;
    const reason = playabilityStatus?.reason || playabilityStatus?.messages?.[0] || '';
    if (reason) {
      throw new Error(`页面返回播放错误: ${reason}`);
    }
    throw new Error('页面中未包含字幕轨道');
  }
  
  return JSON.stringify(parsed);
}

